2886	/****************************************************************************
2887	 * WiFi连接线程 - 后台执行避免阻塞UI
2888	 ****************************************************************************/
2889	
2890	static void *wifi_connect_thread(void *arg)
2891	{
2892	  (void)arg;
2893	
2894	  system("ifup wlan0");
2895	  usleep(100000);                   /* 等待100ms */
2896	  system("wapi mode wlan0 2");      /* 设置为station模式 */
2897	  usleep(50000);
2898	  system("wapi psk wlan0 12345678 3");  /* 设置密码 */
2899	  usleep(50000);
2900	  system("wapi essid wlan0 ZTE-kSQCKP-5G 1");  /* 设置SSID */
2901	  usleep(100000);
2902	  system("ifup wlan0");             /* 再次启动确保连接 */
2903	  usleep(300000);                   /* 等待300ms让WiFi连接 */
2904	  system("renew wlan0");            /* DHCP获取IP地址 */
2905	
2906	  /* 等待真正的IP地址就绪，而不是用固定延时。
2907	   * DHCP可能需要数秒才能完成，固定延时会导致DNS失败和重连循环。 */
2908	  struct in_addr ip_addr;
2909	  int ip_wait;
2910	  for (ip_wait = 0; ip_wait < 30 && g_app.app_running; ip_wait++)
2911	    {
2912	      if (netlib_get_ipv4addr("wlan0", &ip_addr) == 0 &&
2913	          ip_addr.s_addr != 0)
2914	        {
2915	          break;
2916	        }
2917	      usleep(500000);               /* 每500ms检查一次 */
2918	    }
2919	
2920	  s_wifi_ready = true;
2921	  return NULL;
2922	}
