    uint16_t width;             /* display area width  (pixels) */
    uint16_t height;            /* display area height (pixels) */
    uint16_t offset_x;          /* display area X offset in buffer */
    uint16_t offset_y;          /* display area Y offset in buffer */
    union {
        uint8_t *buffer;
        uint8_t *y_buffer;
    };
    uint8_t *u_buffer;
    uint8_t *v_buffer;
    uint32_t stride;            /* buffer stride in bytes */
    uint8_t  dec_mode;
    uint32_t dec_format;        /* hal_lcdc_dec_format_e */
    bool     tile_mode;
    bool     swap_rb;
    uint16_t data_delay;
    uint16_t buf_width;         /* actual buffer width  (pixels) */
    uint16_t buf_height;        /* actual buffer height (pixels) */
};

