input.new_string:
/* Shift LCDC layer to eliminate left white border.
 * We reconfigure the GRA layer offset_x so the LCDC reads
 * pixels starting at the correct position in the framebuffer. */
{
    int fb_fd = open("/dev/fb0", O_RDONLY);
    if (fb_fd >= 0) {
        struct fb_planeinfo_s pinfo;
        if (ioctl(fb_fd, FBIOGET_PLANEINFO,
                  (unsigned long)(uintptr_t)&pinfo) == 0) {
            struct lcdc_layer_config_t cfg;
            memset(&cfg, 0, sizeof(cfg));
            cfg.enable   = true;
            cfg.format   = 11;  /* LCDC_CFMT_RGB565 */
            cfg.width    = 454; /* RM69330 panel width */
            cfg.height   = 454;
            cfg.offset_x = LCDC_DISPLAY_OFFSET_X;
            cfg.offset_y = 0;
            cfg.buffer   = (uint8_t *)pinfo.fbmem;
            cfg.stride   = 464 * 2; /* LCDC_WIDTH * bytes_per_pixel */
            cfg.buf_width  = 464;
            cfg.buf_height = 454;
            lcdc_layer_config(LCDC_LAYER_GRA, &cfg);
        }
        close(fb_fd);
    }
}

