/* Fix left white border: register CASET with hstart=0 via the
 * LCDC command queue. It will be sent at the next framedone IRQ. */
{
    lcdc_cmd_node_t cmd;
    cmd.cmd     = 0x2a;  /* CASET */
    cmd.count   = 4;
    cmd.optype  = LPCMD_TYPE_WRITE;
    cmd.params[0] = 0;            /* hstart high byte */
    cmd.params[1] = 0;            /* hstart low byte  */
    cmd.params[2] = (454 - 1) >> 8;  /* hend high byte */
    cmd.params[3] = (454 - 1) & 0xff; /* hend low byte  */
    bes_lcdc_register_cmds(&cmd, 1, 0);
    bes_lcdc_cmds_flush();
}

