59	#define PWR_BUTTON_BIT  (1 << 0)
60	
61	static void *power_btn_thread(void *arg)
62	{
63	    (void)arg;
64	    int fd = open("/dev/buttons", O_RDONLY);
65	    if (fd < 0) {
66	        printf("[watch_start] Failed to open /dev/buttons: %d\n", errno);
67	        return NULL;
68	    }
69	
70	    btn_buttonset_t prev_state = 0;
71	    struct pollfd fds[1];
72	    fds[0].fd     = fd;
73	    fds[0].events = POLLIN;
74	
75	    while (1) {
76	        int ret = poll(fds, 1, -1);  /* 阻塞等待按钮事件 */
77	        if (ret > 0 && (fds[0].revents & POLLIN)) {
78	            btn_buttonset_t state = 0;
79	            ssize_t n = read(fd, &state, sizeof(state));
80	            if (n == sizeof(state)) {
81	                /* 检测电源键的按下边沿（从0变1） */
82	                btn_buttonset_t pressed = state & ~prev_state;
83	                if (pressed & PWR_BUTTON_BIT) {
84	                    printf("[watch_start] Power button pressed! state=0x%x\n",
85	                           (unsigned)state);
86	                    lv_async_call(power_btn_async_cb, NULL);
87	                }
88	                prev_state = state;
89	            }
90	        }
91	    }
92	
93	    close(fd);
94	    return NULL;
95	}
