137	  } else {
138	    event = KEY_RELEASE;
139	  }
140	  return event;
141	}
142	
143	static void set_current_key_event(int id)
144	{
145	  if (id >= NUM_BUTTONS){
146	    return ;
147	  }
148	
149	  g_gpio_current_status[id] = get_event(id);
150	}
151	
152	static enum KEY_EVENT get_current_key_event(int id)
153	{
154	  if (id >= NUM_BUTTONS){
155	    return KEY_EVENT_NUM;
156	  }
157	  return g_gpio_current_status[id];
158	}
159	
160	static void gpio_irq_callback(enum HAL_GPIO_PIN_T pin)
161	{
162	  int i = 0;
163	  enum KEY_EVENT event = KEY_EVENT_NUM;
164	  for (i = 0; i < NUM_BUTTONS; ++i) {
165	    if (cfg_hw_gpio_key_cfg[i].key_config.pin == (enum HAL_IOMUX_PIN_T)pin) {
166	      struct HAL_GPIO_IRQ_CFG_T gpio_irq_cfg =
167	        {1, 1, HAL_GPIO_IRQ_TYPE_EDGE_SENSITIVE, 0, gpio_irq_callback };
168	      set_current_key_event(i);
169	      event = get_current_key_event(i);
170	      if (cfg_hw_gpio_key_cfg[i].key_down == HAL_KEY_GPIOKEY_VAL_LOW) {
171	          if (event == KEY_RELEASE){
172	            gpio_irq_cfg.irq_polarity = HAL_GPIO_IRQ_POLARITY_LOW_FALLING;
173	          } else if (event == KEY_PRESS){
174	            gpio_irq_cfg.irq_polarity = HAL_GPIO_IRQ_POLARITY_HIGH_RISING;
175	          }
176	      }
177	      else {
178	         if (event == KEY_PRESS){
179	            gpio_irq_cfg.irq_polarity = HAL_GPIO_IRQ_POLARITY_LOW_FALLING;
180	          } else if (event == KEY_RELEASE){
181	            gpio_irq_cfg.irq_polarity = HAL_GPIO_IRQ_POLARITY_HIGH_RISING;
182	          }
183	      }
184	
185	      hal_gpio_setup_irq((enum HAL_GPIO_PIN_T)cfg_hw_gpio_key_cfg[i].key_config.pin, &gpio_irq_cfg);
186	
187	      button_key_irq(cfg_hw_gpio_key_cfg[i].key_code, 0);
188	    }
189	  }
190	}
191	
192	static void setup_button_gpio(void)
193	{
194	  int i = 0;
195	  struct HAL_IOMUX_PIN_FUNCTION_MAP gpio_map[] = {
196	          {0,  HAL_IOMUX_FUNC_AS_GPIO, HAL_IOMUX_PIN_VOLTAGE_VIO, HAL_IOMUX_PIN_PULLUP_ENABLE}};
197	
198	  for (i = 0; i < NUM_BUTTONS; ++i) {
199	    memcpy(&gpio_map, &cfg_hw_gpio_key_cfg[i].key_config, sizeof(struct HAL_IOMUX_PIN_FUNCTION_MAP));
200	    hal_iomux_init(gpio_map, ARRAY_SIZE(gpio_map));
201	    hal_gpio_pin_set_dir((enum HAL_GPIO_PIN_T)cfg_hw_gpio_key_cfg[i].key_config.pin, HAL_GPIO_DIR_IN, 1);
202	
203	    struct HAL_GPIO_IRQ_CFG_T gpio_irq_cfg =
204	      {1, 1, HAL_GPIO_IRQ_TYPE_EDGE_SENSITIVE, 0, gpio_irq_callback };
205	
206	      if (cfg_hw_gpio_key_cfg[i].key_down == HAL_KEY_GPIOKEY_VAL_LOW) {
207	          gpio_irq_cfg.irq_polarity = HAL_GPIO_IRQ_POLARITY_LOW_FALLING;
208	      }
209	      else {
210	          gpio_irq_cfg.irq_polarity = HAL_GPIO_IRQ_POLARITY_HIGH_RISING;
211	      }
212	      hal_gpio_setup_irq((enum HAL_GPIO_PIN_T)cfg_hw_gpio_key_cfg[i].key_config.pin, &gpio_irq_cfg);
213	    }
214	}
215	#endif
216	
217	uint32_t board_button_initialize(void)
218	{
219	  memset(irqhandlers, 0, sizeof(struct gpio_button_irq));
220	#if defined(CONFIG_BUTTON_USE_GPIO)
221	  setup_button_gpio();
222	#else
223	  nuttx_hal_key_open(0, button_key_irq);
224	#endif
225	  return NUM_BUTTONS;
226	}
227	
228	/****************************************************************************
229	 * Name: board_buttons
230	 *
231	 * Description:
232	 *   After board_button_initialize() has been called, board_buttons() may be
233	 *   called to collect the state of all buttons.  board_buttons() returns an
234	 *   32-bit bit set with each bit associated with a button.  See the BUTTON*
235	 *   definitions above for the meaning of each bit in the returned value.
236	 *
237	 ****************************************************************************/
238	
239	uint32_t board_buttons(void)
240	{
241	#if defined(CONFIG_BUTTON_USE_GPIO)
242	  int i = 0;
243	  uint32_t ret = 0;
244	  for (i = 0; i < NUM_BUTTONS; ++i) {
245	      if (cfg_hw_gpio_key_cfg[i].key_down == HAL_KEY_GPIOKEY_VAL_LOW) {
246	        if (hal_gpio_pin_get_val(cfg_hw_gpio_key_cfg[i].key_config.pin) == 0) {
247	          ret |= 1<<i;
248	        }
249	      }
250	      else {
251	        if (hal_gpio_pin_get_val(cfg_hw_gpio_key_cfg[i].key_config.pin) == 1) {
252	          ret |= 1<<i;
253	        }
254	      }
255	  }
256	#else
257	  uint32_t ret = nuttx_hal_key_get_status(NUM_BUTTONS);
258	#endif
259	
260	  if (button_special_processer_cb != NULL)
261	    {
262	      ret = button_special_processer_cb(ret);
263	    }
264	
265	  iinfo("ret = 0x%x\n", ret);
266	  return ret;
267	}
268	
269	/****************************************************************************
270	 * Name: board_button_irq
271	 *
272	 * Description:
273	 *   This function may be called to register an interrupt handler that will
274	 *   be called when a button is depressed or released.  The ID value is one
275	 *   of the BUTTON* definitions provided above.
276	 *
277	 *
278	 ****************************************************************************/
279

